def validate_variables(prompt, data):
    required = set(prompt.input_variables)   # 模板还需的变量
    bound = set(prompt.partial_variables)    # 已 partial 绑定的变量
    provided = set(data)
    problems = []
    for name in sorted(required - provided):
        problems.append(f"缺少必需变量: {name}")
    for name in sorted(provided - required - bound):
        problems.append(f"多传了无用变量: {name}")
    return problems
